class Solution {
    struct Fenwick {
        vector<int> tree;
        int n;
        Fenwick(int n) : n(n), tree(n + 1, 0) {}
        void update(int i, int delta) {
            i++;
            while (i <= n) { tree[i] += delta; i += i & (-i); }
        }
        int query(int i) {
            i++;
            int s = 0;
            while (i > 0) { s += tree[i]; i -= i & (-i); }
            return s;
        }
    };
public:
    long long countOperationsToEmptyArray(vector<int>& nums) {
        int n = nums.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b) { return nums[a] < nums[b]; });

        Fenwick ft(n);
        for (int i = 0; i < n; i++) ft.update(i, 1);

        long long ans = 0;
        int f = 0;
        for (int i = 0; i < n; i++) {
            int qi = idx[i];
            int cnt;
            if (f <= qi) {
                cnt = ft.query(qi) - (f > 0 ? ft.query(f - 1) : 0);
            } else {
                cnt = (ft.query(n - 1) - (f > 0 ? ft.query(f - 1) : 0)) + ft.query(qi);
            }
            ans += cnt;
            ft.update(qi, -1);
            f = (qi + 1) % n;
        }
        return ans;
    }
};
